-- =============================================================================
-- EU research projects in which NVIDIA worked with French partners (14)
-- =============================================================================
-- Source: scanR project records (CORDIS data), extracted 12 Nov 2026; see
-- data/nvidia_france_2026/sources/eu_projects_french.json. One project per EU
-- project; links to NVIDIA and each French partner (lab sub-entries merged into
-- their parent; the two STMicroelectronics sites and two Vranken entities
-- combined); each funded partner's EU contribution recorded as a European
-- Commission grant. Existing Owkin and Iktos MELLODDY grants kept (dedup on
-- source_url). legacy_source on new organisations: 'nvidia_france_november_2026'.
-- Applied 12 Nov 2026 as four statements (orgs, projects, links, grants);
-- grant descriptions were lightly tidied at apply time (partner display names).
-- =============================================================================
BEGIN;
INSERT INTO organizations (id,name,slug,organization_type,description,status,country,legacy_source,created_at,updated_at)
SELECT uuid_generate_v4(), x->>'name', x->>'slug', (x->>'t')::organization_type, x->>'d', 'active'::organization_status, 'France', 'nvidia_france_november_2026', NOW(), NOW()
FROM json_array_elements('[{"slug":"airbus-ds-slc","name":"Airbus DS SLC","t":"corporate","d":"Airbus Defence and Space secure land communications unit."},{"slug":"arianegroup","name":"ArianeGroup","t":"corporate","d":"Space launcher maker (Airbus-Safran joint venture)."},{"slug":"centrale-lyon","name":"École Centrale de Lyon","t":"university","d":"Engineering school in Écully (Lyon)."},{"slug":"vranken-pommery","name":"Vranken-Pommery","t":"corporate","d":"Champagne house (Reims)."},{"slug":"eurecom","name":"EURECOM","t":"university","d":"Graduate school and research centre in digital science at Sophia Antipolis."},{"slug":"globeeye","name":"Globeeye","t":"startup","d":"French Earth-observation analytics company."},{"slug":"servier","name":"Servier","t":"corporate","d":"French pharmaceutical group (Institut de recherches Servier)."},{"slug":"insa-rennes","name":"INSA Rennes","t":"university","d":"Engineering school in Rennes."},{"slug":"meteo-france","name":"Météo-France","t":"public_agency","d":"French national meteorological service."},{"slug":"neurobus","name":"Neurobus","t":"startup","d":"French neuromorphic computing company."},{"slug":"nokia-networks-france","name":"Nokia Networks France","t":"corporate","d":"French arm of Nokia''s networks business."},{"slug":"observatoire-de-paris","name":"Observatoire de Paris","t":"research_lab","d":"Astronomy research institution (PSL)."},{"slug":"substra","name":"Substra","t":"nonprofit","d":"Open-source federated-learning software first developed by Owkin for MELLODDY."},{"slug":"technext","name":"Technext","t":"startup","d":"French technology company (EdgeAI-Trust partner)."},{"slug":"universite-clermont-auvergne","name":"Université Clermont Auvergne","t":"university","d":"Public university in Clermont-Ferrand."},{"slug":"universite-marie-et-louis-pasteur","name":"Université Marie et Louis Pasteur","t":"university","d":"Public university in Besançon (formerly Université de Franche-Comté)."},{"slug":"universite-sorbonne-paris-nord","name":"Université Sorbonne Paris Nord","t":"university","d":"Public university in Villetaneuse and Bobigny."},{"slug":"yooz","name":"Yooz","t":"startup","d":"French invoice-automation software company."},{"slug":"zettascale","name":"ZettaScale Technology","t":"startup","d":"French data-connectivity software company."},{"slug":"chimie-paristech","name":"Chimie ParisTech","t":"university","d":"Chemistry engineering school in Paris (PSL)."}]'::json) x WHERE NOT EXISTS (SELECT 1 FROM organizations o WHERE o.slug=x->>'slug');
INSERT INTO projects (id,name,slug,summary,technical_focus,sector,commercialization_status,first_evidence_date,is_public,website_url,created_at,updated_at)
SELECT uuid_generate_v4(), x->>'name', x->>'slug', x->>'summary', ARRAY[x->>'focus'], 'EU research', 'research', (x->>'start')::date, FALSE, x->>'url', NOW(), NOW()
FROM json_array_elements('[{"name":"COSINE","slug":"eu-cosine","url":"https://cordis.europa.eu/project/id/765739","start":"2018-01-01","focus":"computational chemistry","summary":"Training network for COmputational Spectroscopy In Natural sciences and Engineering. EU Horizon 2020 project (Marie Skłodowska-Curie action), 2018-01 to 2021-12; EU contribution €3,745,979. NVIDIA took part without EU funding. French partners'' EU funding totals €262,876 (École nationale supérieure de chimie de Paris €262,876)."},{"name":"NEWTON","slug":"eu-newton","url":"https://cordis.europa.eu/project/id/101227315","start":"2026-03-01","focus":"6g","summary":"NovEl tEchnologies for converged Wireless-opTical cOnfiguratioNs. EU Horizon Europe project (Marie Skłodowska-Curie action), 2026-03 to 2030-02; EU contribution €4,348,888. NVIDIA received €335,890. French partners'' EU funding totals €629,338 (EURECOM €629,338)."},{"name":"EdgeAI-Trust","slug":"eu-edgeai-trust","url":"https://cordis.europa.eu/project/id/101139892","start":"2024-05-01","focus":"edge ai","summary":"Decentralized Edge Intelligence: Advancing Trust, Safety, and Sustainability in Europe. EU Horizon Europe project (Innovation action), 2024-05 to 2027-04; EU contribution €11,006,209. NVIDIA received €225,000. French partners'' EU funding totals €2,090,954 (Stmicroelectronics (grenoble 2) sas €853,960; Stmicroelectronics (rousset) sas €681,469; Zettascale technology sarl €160,469; Vranken-pommery production €158,285; Technext €109,937; Université de Reims Champagne-Ardenne €90,417; Compagnie vranken €36,417; HawAI.Tech (no EU funds))."},{"name":"MicrocombSys","slug":"eu-microcombsys","url":"https://cordis.europa.eu/project/id/101119968","start":"2023-10-01","focus":"photonics","summary":"Photonic System Engineering with Microcombs. EU Horizon Europe project (Marie Skłodowska-Curie action), 2023-10 to 2027-09; EU contribution €2,788,625. NVIDIA received €301,788. French partners'' EU funding totals €282,694 (Centrale Lyon €282,694)."},{"name":"HiPerNav","slug":"eu-hipernav","url":"https://cordis.europa.eu/project/id/722068","start":"2016-11-01","focus":"medtech","summary":"High Performance Soft-tissue Navigation. EU Horizon 2020 project (Marie Skłodowska-Curie action), 2016-11 to 2021-04; EU contribution €4,041,920. NVIDIA took part without EU funding. French partners'' EU funding totals €788,627 (Institut national de recherche en sciences et technologies du numérique €525,751; Université Sorbonne Paris Nord €262,876)."},{"name":"ThinkingEarth","slug":"eu-thinkingearth","url":"https://cordis.europa.eu/project/id/101130544","start":"2024-01-01","focus":"earth observation","summary":"Copernicus Foundation Models for a Thinking Earth. EU Horizon Europe project (Research and Innovation action), 2024-01 to 2026-12; EU contribution €2,999,875. NVIDIA received €456,375. French partners'' EU funding totals €150,625 (Globeeye €150,625)."},{"name":"CENTRIC","slug":"eu-centric","url":"https://cordis.europa.eu/project/id/101096379","start":"2023-01-01","focus":"6g","summary":"Towards an AI-native, user-centric air interface for 6G networks. EU Horizon Europe project (Research and Innovation action), 2023-01 to 2025-06; EU contribution €4,215,999. NVIDIA received €437,062. French partners'' EU funding totals €796,757 (Sequans communications €433,636; Nokia networks France €363,121)."},{"name":"ELSA","slug":"eu-elsa","url":"https://cordis.europa.eu/project/id/101070617","start":"2022-09-01","focus":"ai safety","summary":"European Lighthouse on Secure and Safe AI. EU Horizon Europe project (Research and Innovation action), 2022-09 to 2026-08; EU contribution €7,434,058. NVIDIA took part without EU funding. French partners'' EU funding totals €680,000 (Valeo comfort and driving assistance €336,250; Institut national de recherche en sciences et technologies du numérique €268,750; Yooz €75,000)."},{"name":"ESCAPE","slug":"eu-escape","url":"https://cordis.europa.eu/project/id/671627","start":"2015-10-01","focus":"hpc","summary":"Energy-efficient SCalable Algorithms for weather Prediction at Exascale. EU Horizon 2020 project (Research and Innovation action), 2015-10 to 2018-09; EU contribution €3,977,952. NVIDIA received €193,335. French partners'' EU funding totals €562,455 (Météo-France €293,175; Bull €269,280)."},{"name":"FLECON-6G","slug":"eu-flecon-6g","url":"https://cordis.europa.eu/project/id/101192462","start":"2025-01-01","focus":"6g","summary":"Flexible Open Architecture and AI-driven Enabling Technologies for a Novel 6G Connectivity Platform. EU Horizon Europe project (Research and Innovation action), 2025-01 to 2027-12; EU contribution €7,971,094. NVIDIA received €427,500. French partners'' EU funding totals €935,572 (EURECOM €547,448; Airbus ds slc €388,125)."},{"name":"ACHIEVE","slug":"eu-achieve","url":"https://cordis.europa.eu/project/id/765866","start":"2017-10-01","focus":"computer vision","summary":"AdvanCed Hardware/Software Components for Integrated/Embedded Vision SystEms. EU Horizon 2020 project (Marie Skłodowska-Curie action), 2017-10 to 2022-03; EU contribution €2,266,908. NVIDIA took part without EU funding. French partners'' EU funding totals €525,751 (Université Clermont Auvergne €262,876; Université Marie et Louis Pasteur €262,876)."},{"name":"MINDnet","slug":"eu-mindnet","url":"https://cordis.europa.eu/project/id/101226674","start":"2026-01-01","focus":"neuromorphic","summary":"Neuromorphic computing and signal processing training network. EU Horizon Europe project (Marie Skłodowska-Curie action), 2026-01 to 2029-12; EU contribution €4,664,170. NVIDIA took part without EU funding. French partners'' EU funding totals €0 (NEUROBUS (no EU funds))."},{"name":"Rising STARS","slug":"eu-rising-stars","url":"https://cordis.europa.eu/project/id/873120","start":"2020-02-01","focus":"space","summary":"RISE International Network for Solutions Technologies and Applications of Real-time Systems. EU Horizon 2020 project (Marie Skłodowska-Curie action), 2020-02 to 2025-11; EU contribution €634,800. NVIDIA was a funded member but no amount is published. French partners'' EU funding totals €414,000 (Observatoire de Paris €165,600; Institut national des sciences appliquées de Rennes €138,000; Thales group €55,200; ArianeGroup €55,200; Kalray (no EU funds))."},{"name":"MELLODDY","slug":"eu-melloddy","url":"https://cordis.europa.eu/project/id/831472","start":"2019-06-01","focus":"drug discovery","summary":"MachinE Learning Ledger Orchestration for Drug DiscoverY. EU Horizon 2020 project (Research and Innovation action), 2019-06 to 2022-05; EU contribution €8,000,000. NVIDIA was a funded member but no amount is published. French partners'' EU funding totals €3,885,519 (Owkin France €2,683,635; Substra €858,482; Iktos €343,402; Institut de recherches servier (no EU funds))."}]'::json) x WHERE NOT EXISTS (SELECT 1 FROM projects p WHERE p.slug=x->>'slug');
INSERT INTO project_links (id,project_id,organization_id,role,start_date,end_date,status,created_at)
SELECT uuid_generate_v4(), pr.id, o.id, x->>'role', (x->>'sd')::date, (x->>'ed')::date, 'verified', NOW()
FROM json_array_elements('[{"p":"eu-cosine","o":"nvidia","role":"partner","sd":"2018-01-01","ed":"2021-12-31"},{"p":"eu-cosine","o":"chimie-paristech","role":"partner","sd":"2018-01-01","ed":"2021-12-31"},{"p":"eu-newton","o":"nvidia","role":"partner","sd":"2026-03-01","ed":"2030-02-28"},{"p":"eu-newton","o":"eurecom","role":"partner","sd":"2026-03-01","ed":"2030-02-28"},{"p":"eu-edgeai-trust","o":"nvidia","role":"partner","sd":"2024-05-01","ed":"2027-04-30"},{"p":"eu-edgeai-trust","o":"technext","role":"partner","sd":"2024-05-01","ed":"2027-04-30"},{"p":"eu-edgeai-trust","o":"universite-de-reims-champagne-ardenne","role":"partner","sd":"2024-05-01","ed":"2027-04-30"},{"p":"eu-edgeai-trust","o":"vranken-pommery","role":"partner","sd":"2024-05-01","ed":"2027-04-30"},{"p":"eu-edgeai-trust","o":"stmicroelectronics","role":"partner","sd":"2024-05-01","ed":"2027-04-30"},{"p":"eu-edgeai-trust","o":"zettascale","role":"partner","sd":"2024-05-01","ed":"2027-04-30"},{"p":"eu-edgeai-trust","o":"hawaitech","role":"partner","sd":"2024-05-01","ed":"2027-04-30"},{"p":"eu-microcombsys","o":"nvidia","role":"partner","sd":"2023-10-01","ed":"2027-09-30"},{"p":"eu-microcombsys","o":"centrale-lyon","role":"partner","sd":"2023-10-01","ed":"2027-09-30"},{"p":"eu-hipernav","o":"universite-sorbonne-paris-nord","role":"partner","sd":"2016-11-01","ed":"2021-04-30"},{"p":"eu-hipernav","o":"nvidia","role":"partner","sd":"2016-11-01","ed":"2021-04-30"},{"p":"eu-hipernav","o":"inria","role":"partner","sd":"2016-11-01","ed":"2021-04-30"},{"p":"eu-thinkingearth","o":"nvidia","role":"partner","sd":"2024-01-01","ed":"2026-12-31"},{"p":"eu-thinkingearth","o":"globeeye","role":"partner","sd":"2024-01-01","ed":"2026-12-31"},{"p":"eu-centric","o":"sequans","role":"partner","sd":"2023-01-01","ed":"2025-06-30"},{"p":"eu-centric","o":"nokia-networks-france","role":"partner","sd":"2023-01-01","ed":"2025-06-30"},{"p":"eu-centric","o":"nvidia","role":"partner","sd":"2023-01-01","ed":"2025-06-30"},{"p":"eu-elsa","o":"valeo","role":"partner","sd":"2022-09-01","ed":"2026-08-31"},{"p":"eu-elsa","o":"yooz","role":"partner","sd":"2022-09-01","ed":"2026-08-31"},{"p":"eu-elsa","o":"inria","role":"partner","sd":"2022-09-01","ed":"2026-08-31"},{"p":"eu-elsa","o":"nvidia","role":"partner","sd":"2022-09-01","ed":"2026-08-31"},{"p":"eu-escape","o":"nvidia","role":"partner","sd":"2015-10-01","ed":"2018-09-30"},{"p":"eu-escape","o":"bull","role":"partner","sd":"2015-10-01","ed":"2018-09-30"},{"p":"eu-escape","o":"meteo-france","role":"partner","sd":"2015-10-01","ed":"2018-09-30"},{"p":"eu-flecon-6g","o":"airbus-ds-slc","role":"partner","sd":"2025-01-01","ed":"2027-12-31"},{"p":"eu-flecon-6g","o":"eurecom","role":"partner","sd":"2025-01-01","ed":"2027-12-31"},{"p":"eu-flecon-6g","o":"nvidia","role":"partner","sd":"2025-01-01","ed":"2027-12-31"},{"p":"eu-achieve","o":"universite-clermont-auvergne","role":"partner","sd":"2017-10-01","ed":"2022-03-31"},{"p":"eu-achieve","o":"universite-marie-et-louis-pasteur","role":"partner","sd":"2017-10-01","ed":"2022-03-31"},{"p":"eu-achieve","o":"nvidia","role":"partner","sd":"2017-10-01","ed":"2022-03-31"},{"p":"eu-mindnet","o":"neurobus","role":"partner","sd":"2026-01-01","ed":"2029-12-31"},{"p":"eu-mindnet","o":"nvidia","role":"partner","sd":"2026-01-01","ed":"2029-12-31"},{"p":"eu-rising-stars","o":"nvidia","role":"partner","sd":"2020-02-01","ed":"2025-11-30"},{"p":"eu-rising-stars","o":"thales-group","role":"partner","sd":"2020-02-01","ed":"2025-11-30"},{"p":"eu-rising-stars","o":"observatoire-de-paris","role":"coordinator","sd":"2020-02-01","ed":"2025-11-30"},{"p":"eu-rising-stars","o":"arianegroup","role":"partner","sd":"2020-02-01","ed":"2025-11-30"},{"p":"eu-rising-stars","o":"kalray","role":"partner","sd":"2020-02-01","ed":"2025-11-30"},{"p":"eu-rising-stars","o":"insa-rennes","role":"partner","sd":"2020-02-01","ed":"2025-11-30"},{"p":"eu-melloddy","o":"substra","role":"partner","sd":"2019-06-01","ed":"2022-05-31"},{"p":"eu-melloddy","o":"servier","role":"partner","sd":"2019-06-01","ed":"2022-05-31"},{"p":"eu-melloddy","o":"owkin","role":"coordinator","sd":"2019-06-01","ed":"2022-05-31"},{"p":"eu-melloddy","o":"iktos","role":"partner","sd":"2019-06-01","ed":"2022-05-31"},{"p":"eu-melloddy","o":"nvidia","role":"partner","sd":"2019-06-01","ed":"2022-05-31"}]'::json) x JOIN projects pr ON pr.slug=x->>'p' JOIN organizations o ON o.slug=x->>'o'
WHERE NOT EXISTS (SELECT 1 FROM project_links l WHERE l.project_id=pr.id AND l.organization_id=o.id);
INSERT INTO grants (id,organization_id,grant_name,granting_body,amount_eur,awarded_date,program,description,source_url,created_at,updated_at)
SELECT uuid_generate_v4(), o.id, x->>'name', 'European Commission', (x->>'amt')::numeric, (x->>'d')::date, x->>'prog', x->>'desc', x->>'url', NOW(), NOW()
FROM json_array_elements('[{"o":"chimie-paristech","name":"Horizon 2020 – COSINE (Marie Skłodowska-Curie action)","amt":262875.6,"d":"2018-01-01","prog":"Horizon 2020 · Marie Skłodowska-Curie action","url":"https://cordis.europa.eu/project/id/765739","desc":"EU contribution to École nationale supérieure de chimie de Paris in COSINE (Training network for COmputational Spectroscopy In Natural sciences and Engineering), 2018-01 to 2021-12; consortium included NVIDIA and French partners."},{"o":"nvidia","name":"Horizon Europe – NEWTON (Marie Skłodowska-Curie action)","amt":335890.08,"d":"2026-03-01","prog":"Horizon Europe · Marie Skłodowska-Curie action","url":"https://cordis.europa.eu/project/id/101227315","desc":"EU contribution to NVIDIA entities in NEWTON (NovEl tEchnologies for converged Wireless-opTical cOnfiguratioNs), 2026-03 to 2030-02; consortium included NVIDIA and French partners."},{"o":"eurecom","name":"Horizon Europe – NEWTON (Marie Skłodowska-Curie action)","amt":629338.32,"d":"2026-03-01","prog":"Horizon Europe · Marie Skłodowska-Curie action","url":"https://cordis.europa.eu/project/id/101227315","desc":"EU contribution to EURECOM in NEWTON (NovEl tEchnologies for converged Wireless-opTical cOnfiguratioNs), 2026-03 to 2030-02; consortium included NVIDIA and French partners."},{"o":"nvidia","name":"Horizon Europe – EdgeAI-Trust (Innovation action)","amt":225000.0,"d":"2024-05-01","prog":"Horizon Europe · Innovation action","url":"https://cordis.europa.eu/project/id/101139892","desc":"EU contribution to NVIDIA entities in EdgeAI-Trust (Decentralized Edge Intelligence: Advancing Trust, Safety, and Sustainability in Europe), 2024-05 to 2027-04; consortium included NVIDIA and French partners."},{"o":"technext","name":"Horizon Europe – EdgeAI-Trust (Innovation action)","amt":109936.75,"d":"2024-05-01","prog":"Horizon Europe · Innovation action","url":"https://cordis.europa.eu/project/id/101139892","desc":"EU contribution to Technext in EdgeAI-Trust (Decentralized Edge Intelligence: Advancing Trust, Safety, and Sustainability in Europe), 2024-05 to 2027-04; consortium included NVIDIA and French partners."},{"o":"universite-de-reims-champagne-ardenne","name":"Horizon Europe – EdgeAI-Trust (Innovation action)","amt":90417.25,"d":"2024-05-01","prog":"Horizon Europe · Innovation action","url":"https://cordis.europa.eu/project/id/101139892","desc":"EU contribution to Université de Reims Champagne-Ardenne in EdgeAI-Trust (Decentralized Edge Intelligence: Advancing Trust, Safety, and Sustainability in Europe), 2024-05 to 2027-04; consortium included NVIDIA and French partners."},{"o":"vranken-pommery","name":"Horizon Europe – EdgeAI-Trust (Innovation action)","amt":194702.19,"d":"2024-05-01","prog":"Horizon Europe · Innovation action","url":"https://cordis.europa.eu/project/id/101139892","desc":"EU contribution to Compagnie vranken, Vranken-pommery production in EdgeAI-Trust (Decentralized Edge Intelligence: Advancing Trust, Safety, and Sustainability in Europe), 2024-05 to 2027-04; consortium included NVIDIA and French partners."},{"o":"stmicroelectronics","name":"Horizon Europe – EdgeAI-Trust (Innovation action)","amt":1535428.75,"d":"2024-05-01","prog":"Horizon Europe · Innovation action","url":"https://cordis.europa.eu/project/id/101139892","desc":"EU contribution to Stmicroelectronics (grenoble 2) sas, Stmicroelectronics (rousset) sas in EdgeAI-Trust (Decentralized Edge Intelligence: Advancing Trust, Safety, and Sustainability in Europe), 2024-05 to 2027-04; consortium included NVIDIA and French partners."},{"o":"zettascale","name":"Horizon Europe – EdgeAI-Trust (Innovation action)","amt":160468.75,"d":"2024-05-01","prog":"Horizon Europe · Innovation action","url":"https://cordis.europa.eu/project/id/101139892","desc":"EU contribution to Zettascale technology sarl in EdgeAI-Trust (Decentralized Edge Intelligence: Advancing Trust, Safety, and Sustainability in Europe), 2024-05 to 2027-04; consortium included NVIDIA and Fren